// === Tab: mySketch ===
// A fork/conversion of Perlin noise drawing from Processing to P5.js 
// original by Anna Fedchenko // https://www.openprocessing.org/sketch/688380

var nums = 150; //originally 150
var num_clust =10; //originally 10
var noiseScale = 300; 
var posx= [];
var posy= [];
var particles = [];
var theta;
var r = [];
var dispR = 0.5;
var pCount = 0;

function setup(){

	//fullScreen();
    createCanvas(1000,1000);
	background(color('#C477BA'));

    theta = float(-PI/2.0);

	// init clusters
	for(var i = 0; i < num_clust; i++)  
	{
		posx[i]= int(random(width));
		posy[i]= int(random(height));
		r[i] = int(random(50,120));
	} //for

  // init particles
	for(var j = 0; j < num_clust; j++){
        particles[j] = [];
		for(i = 0; i < nums; i++){ 
            var x = posx[j] + r[j] * sin(theta);
            var y = posy[j] + r[j] * cos(theta);
			particles[j][i] = new Particle(x,y);
			theta += float(TWO_PI/nums);
		} //for
	} //for

	for(j=0; j < num_clust; j++){
		for (i = 1; i < 120; i++) { //originally 120
				noStroke();
                fill(lerpColor(color('#D8B1D8'),color('#000000'),i/120.0)); //orig 120
				ellipse(posx[j],posy[j], 2*r[j]-(i), 2*r[j]-(i));
		} //for
	} //for
} // setup

function draw(){
	for(var j=0; j<num_clust;j++){
		for(var i = 0; i < nums; i++){
			particles[j][i].move(); 
			particles[j][i].display(dispR);
		} //for
	} //for   
} //draw

class Particle{
	constructor(x,y){
        this.alpha = 100;
		this.c = color(0,this.alpha);
		this.speed = 0.4;
		this.dir = new createVector(0, 0);
		this.pos = new createVector(x, y);
	}  // constructor

	move(){
		this.angle = noise(this.pos.x/noiseScale, this.pos.y/noiseScale)*TWO_PI;
		this.dir.x = sin(this.angle);
		this.dir.y = cos(this.angle);
		this.dir.mult(this.speed);
		this.pos.add(this.dir);
	} //move

	display(r){ 
		fill(this.c, this.alpha);
		ellipse(this.pos.x, this.pos.y, r, r);
	} //display

} //particle

